    "cssCode": ".loader {\n  --background: linear-gradient(135deg, #23C4F8, #275EFE);\n  --shadow: rgba(39, 94, 254, 0.28);\n  --text: #6C7486;\n  --page: rgba(255, 255, 255, 0.36);\n  --page-fold: rgba(255, 255, 255, 0.52);\n  --duration: 3s;\n  width: 200px;\n  height: 140px;\n  position: relative;\n}\n\n.loader:before, .loader:after {\n  --r: -6deg;\n  content: \"\";\n  position: absolute;\n  bottom: 8px;\n  width: 120px;\n  top: 80%;\n  box-shadow: 0 16px 12px var(--shadow);\n  transform: rotate(var(--r));\n}\n\n.loader:before {\n  left: 4px;\n}\n\n.loader:after {\n  --r: 6deg;\n  right: 4px;\n}\n\n.loader div {\n  width: 100%;\n  height: 100%;\n  border-radius: 13px;\n  position: relative;\n  z-index: 1;\n  perspective: 600px;\n  box-shadow: 0 4px 6px var(--shadow);\n  background-image: var(--background);\n}\n\n.loader div ul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  position: relative;\n}\n\n.loader div ul li {\n  --r: 180deg;\n  --o: 0;\n  --c: var(--page);\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  transform-origin: 100% 50%;\n  color: var(--c);\n  opacity: var(--o);\n  transform: rotateY(var(--r));\n  -webkit-animation: var(--duration) ease infinite;\n  animation: var(--duration) ease infinite;\n}\n\n.loader div ul li:nth-child(2) {\n  --c: var(--page-fold);\n  -webkit-animation-name: page-2;\n  animation-name: page-2;\n}\n\n.loader div ul li:nth-child(3) {\n  --c: var(--page-fold);\n  -webkit-animation-name: page-3;\n  animation-name: page-3;\n}\n\n.loader div ul li:nth-child(4) {\n  --c: var(--page-fold);\n  -webkit-animation-name: page-4;\n  animation-name: page-4;\n}\n\n.loader div ul li:nth-child(5) {\n  --c: var(--page-fold);\n  -webkit-animation-name: page-5;\n  animation-name: page-5;\n}\n\n.loader div ul li svg {\n  width: 90px;\n  height: 120px;\n  display: block;\n}\n\n.loader div ul li:first-child {\n  --r: 0deg;\n  --o: 1;\n}\n\n.loader div ul li:last-child {\n  --o: 1;\n}\n\n.loader span {\n  display: block;\n  left: 0;\n  right: 0;\n  top: 100%;\n  margin-top: 20px;\n  text-align: center;\n  color: var(--text);\n}\n\n@keyframes page-2 {\n  0% {\n    transform: rotateY(180deg);\n    opacity: 0;\n  }\n\n  20% {\n    opacity: 1;\n  }\n\n  35%, 100% {\n    opacity: 0;\n  }\n\n  50%, 100% {\n    transform: rotateY(0deg);\n  }\n}\n\n@keyframes page-3 {\n  15% {\n    transform: rotateY(180deg);\n    opacity: 0;\n  }\n\n  35% {\n    opacity: 1;\n  }\n\n  50%, 100% {\n    opacity: 0;\n  }\n\n  65%, 100% {\n    transform: rotateY(0deg);\n  }\n}\n\n@keyframes page-4 {\n  30% {\n    transform: rotateY(180deg);\n    opacity: 0;\n  }\n\n  50% {\n    opacity: 1;\n  }\n\n  65%, 100% {\n    opacity: 0;\n  }\n\n  80%, 100% {\n    transform: rotateY(0deg);\n  }\n}\n\n@keyframes page-5 {\n  45% {\n    transform: rotateY(180deg);\n    opacity: 0;\n  }\n\n  65% {\n    opacity: 1;\n  }\n\n  80%, 100% {\n    opacity: 0;\n  }\n\n  95%, 100% {\n    transform: rotateY(0deg);\n  }\n}\n"
