    "cssCode": "\n.loader {\n  display: flex;\n  position: relative;\n  justify-items: center;\n  align-items: center;\n  gap: 1rem;\n  height: 55px;\n  width: 200px;\n  overflow: hidden;\n}\n\n.container {\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n  height: 200px;\n  position: relative;\n  align-items: center;\n}\n\n.carousel {\n  display: flex;\n  gap: 1rem;\n  flex-direction: column;\n  position: absolute;\n  width: 100%;\n  transform-origin: center;\n  animation-delay: 2s;\n}\n\n.loader .container:nth-child(3) {\n  justify-content: flex-start;\n  justify-items: flex-start;\n  animation: scroll-up 4s infinite ease-in-out;\n  animation-delay: 3s;\n}\n\n.loader .container:nth-child(2) {\n  justify-content: flex-end;\n  justify-items: flex-end;\n  animation: scroll-down 4s infinite ease-in-out;\n  animation-delay: 3s;\n}\n\n.loader .container:nth-child(1) {\n  justify-content: flex-end;\n  justify-items: flex-end;\n  animation: scroll-down 3s infinite ease-in-out;\n  animation-delay: 3s;\n}\n\n.love {\n  background: red;\n  display: flex;\n  width: 30px;\n  height: 30px;\n  position: relative;\n  align-items: center;\n  justify-content: center;\n  left: 8px;\n  margin: 0.8rem 4px;\n  transform: rotate(45deg);\n  animation-delay: 2s;\n}\n\n.love::before, .love::after {\n  content: '';\n  position: absolute;\n  width: 30px;\n  height: 30px;\n  border-radius: 50%;\n  background: red;\n}\n\n.love::before {\n  left: -16px;\n}\n\n.love::after {\n  top: -16px;\n}\n\n.death {\n  display: flex;\n  width: 100%;\n  height: 55px;\n  position: relative;\n  align-items: center;\n  justify-content: center;\n  animation: rotation 3s infinite ease-in-out;\n  animation-delay: 1s;\n}\n\n.death:after {\n  content: '';\n  height: 63px;\n  position: absolute;\n  border-left: 12px solid red;\n  transform: rotate(45deg);\n  border-radius: 8px;\n  top: -4px;\n}\n\n.death:before {\n  content: '';\n  height: 60px;\n  position: absolute;\n  border-left: 12px solid red;\n  transform: rotate(-45deg);\n}\n\n.loader:hover {\n  animation: none;\n}\n\n.robots {\n  display: flex;\n  width: 100%;\n  height: 55px;\n  justify-content: space-between;\n  background-color: #ff0000;\n  border-radius: 0 8px 8px;\n  padding: 8px;\n  animation-delay: 5s;\n}\n\n.robots::after {\n  content: '';\n  width: 12px;\n  height: 12px;\n  top: 0;\n  left: 0;\n  background-color: #ffffff;\n  border-radius: 50%;\n  animation-delay: 2s;\n  animation: blink 0.5s 2 forwards;\n}\n\n.robots::before {\n  content: '';\n  width: 12px;\n  height: 12px;\n  top: 0;\n  left: 0;\n  background-color: #ffffff;\n  border-radius: 50%;\n  animation-delay: 2s;\n  animation: blink 0.5s 2 forwards;\n}\n\n@keyframes scroll-up {\n  0% {\n    transform: translateY(0);\n    filter: blur(0);\n  }\n\n  30% {\n    transform: translateY(-150%);\n    filter: blur(10px);\n  }\n\n  60% {\n    transform: translateY(0);\n    filter: blur(0px);\n  }\n}\n\n@keyframes scroll-down {\n  0% {\n    transform: translateY(0);\n    filter: blur(0);\n  }\n\n  30% {\n    transform: translateY(150%);\n    filter: blur(10px);\n  }\n\n  60% {\n    transform: translateY(0);\n    filter: blur(0px);\n  }\n}\n\n@keyframes rotation {\n  20%, 100% {\n    transform: rotate(180deg);\n  }\n}\n\n@keyframes blink {\n  0% {\n    height: 0;\n  }\n\n  20% {\n    height: 12px;\n  }\n\n  100% {\n    height: 12px;\n  }\n}"
